import{R as e,e as a,f as o,U as i}from"./chunks/framework.ywem4qy5.js";const g=JSON.parse('{"title":"Akismet","description":"","frontmatter":{},"headers":[],"relativePath":"integrations/captchas/akismet.md","filePath":"integrations/captchas/akismet.md","lastUpdated":1775908585000}'),s={name:"integrations/captchas/akismet.md"};function n(r,t,l,h,m,c){return a(),o("div",null,[...t[0]||(t[0]=[i('<h1 id="akismet" tabindex="-1">Akismet <a class="header-anchor" href="#akismet" aria-label="Permalink to &quot;Akismet&quot;">​</a></h1><p>Follow the below steps to connect Formie to the Akismet API.</p><h3 id="step-1-open-the-captcha-settings" tabindex="-1">Step 1. Open the Captcha Settings <a class="header-anchor" href="#step-1-open-the-captcha-settings" aria-label="Permalink to &quot;Step 1. Open the Captcha Settings&quot;">​</a></h3><ol><li>Navigate to <strong>Formie</strong> → <strong>Settings</strong> → <strong>Captchas</strong>.</li><li>Select <strong>Akismet</strong> in the left-hand sidebar.</li><li>Turn on <strong>Enabled</strong>.</li></ol><h3 id="step-2-get-your-akismet-api-key" tabindex="-1">Step 2. Get your Akismet API Key <a class="header-anchor" href="#step-2-get-your-akismet-api-key" aria-label="Permalink to &quot;Step 2. Get your Akismet API Key&quot;">​</a></h3><ol><li>Go to <a href="https://akismet.com/" target="_blank" rel="noreferrer">Akismet</a> and create an account, or sign in to an existing one.</li><li>After signing up, Akismet will email you your API key. You can also find it in your Akismet account.</li><li>Copy the API key.</li></ol><h3 id="step-3-connect-formie-to-akismet" tabindex="-1">Step 3. Connect Formie to Akismet <a class="header-anchor" href="#step-3-connect-formie-to-akismet" aria-label="Permalink to &quot;Step 3. Connect Formie to Akismet&quot;">​</a></h3><ol><li>Paste the API key into the <strong>API Key</strong> field in Formie.</li><li>Save the captcha settings.</li></ol><h3 id="step-4-form-setting" tabindex="-1">Step 4. Form Setting <a class="header-anchor" href="#step-4-form-setting" aria-label="Permalink to &quot;Step 4. Form Setting&quot;">​</a></h3><ol><li>Go to the form you want to protect.</li><li>Enable <strong>Akismet</strong> for that form.</li><li>For multi-page forms, turn on <strong>Show on All Pages</strong> if the spam check should run on every page instead of only the final submit step.</li><li>Save the form.</li></ol><p>Akismet screens submissions in the background, so there is no visible challenge on the front end.</p>',11)])])}const k=e(s,[["render",n]]);export{g as __pageData,k as default};
